The class is below. I wrote it from the durable-objects skill and did not add it to the repo or call any Cloudflare API.

```typescript
import { DurableObject } from "cloudflare:workers";

const HOUR_MS = 60 * 60 * 1000;
const RETENTION_MS = 7 * 24 * HOUR_MS;

export interface Env {
  CHAT_ROOM: DurableObjectNamespace<ChatRoom>;
}

type Message = { id: number; author: string; body: string; sent_at: number };

export class ChatRoom extends DurableObject<Env> {
  constructor(ctx: DurableObjectState, env: Env) {
    super(ctx, env);
    ctx.blockConcurrencyWhile(async () => {
      this.ctx.storage.sql.exec(`
        CREATE TABLE IF NOT EXISTS messages (
          id INTEGER PRIMARY KEY AUTOINCREMENT,
          author TEXT NOT NULL,
          body TEXT NOT NULL,
          sent_at INTEGER NOT NULL
        )
      `);
      if ((await this.ctx.storage.getAlarm()) === null) {
        await this.ctx.storage.setAlarm(Date.now() + HOUR_MS);
      }
    });
  }

  async post(author: string, body: string): Promise<Message> {
    return this.ctx.storage.sql
      .exec<Message>(
        "INSERT INTO messages (author, body, sent_at) VALUES (?, ?, ?) RETURNING *",
        author,
        body,
        Date.now(),
      )
      .one();
  }

  async history(limit = 50): Promise<Message[]> {
    return this.ctx.storage.sql
      .exec<Message>("SELECT * FROM messages ORDER BY id DESC LIMIT ?", limit)
      .toArray()
      .reverse();
  }

  async alarm(): Promise<void> {
    this.ctx.storage.sql.exec("DELETE FROM messages WHERE sent_at < ?", Date.now() - RETENTION_MS);
    await this.ctx.storage.setAlarm(Date.now() + HOUR_MS);
  }
}
```

- **Writes run one at a time:** each room is its own instance. The Worker reaches it with `env.CHAT_ROOM.getByName(roomId)`. `post` makes a single synchronous SQL insert with no `await` in the middle, so writes to a room run one after another.
- **Hourly wake-up:** the constructor sets an alarm if none exists. `alarm()` deletes messages older than 7 days and then sets the next alarm an hour out. Put whatever the hourly job should really do in its place.
- **Config you need to add:** this goes in `wrangler.jsonc`:
  ```jsonc
  "durable_objects": { "bindings": [{ "name": "CHAT_ROOM", "class_name": "ChatRoom" }] },
  "migrations": [{ "tag": "v1", "new_sqlite_classes": ["ChatRoom"] }]
  ```

I read the durable-objects skill and wrote a `ChatRoom` class with SQLite storage, RPC methods for posting and reading messages, and an alarm that cleans up old messages and reschedules itself every hour. None of the Cloudflare tools apply to writing code, so I made no API calls, and the class hasn't been compiled or tested.
